module.exports = /*#__PURE__*/JSON.parse('[{"chapterId":1,"title":"One God","toneFocus":"Gentle reminder: trace every thought back to God’s oneness, holding questions close while celebrating the comfort of divine unity. It invites patience, softens doubts, and champions steady growth. It celebrates resilience and keeps hearts hopeful daily."},{"chapterId":2,"title":"The Qur\'an","toneFocus":"Encourage slow, reflective encounters with Qur’anic verses that welcome curiosity and keep silence as part of the conversation. It invites patience, softens doubts, and champions steady growth. It celebrates resilience and keeps hearts hopeful daily."},{"chapterId":3,"title":"The Prophet","toneFocus":"Share prophetic stories with warmth, highlighting mercy and relatability over perfection while keeping the tone conversational. It invites patience, softens doubts, and champions steady growth. It celebrates resilience and keeps hearts hopeful daily."},{"chapterId":4,"title":"Main Practices","toneFocus":"Present practices as supportive anchors offer flexible, encouraging language that lets readers experiment without fear of failure. It invites patience, softens doubts, and champions steady growth. It celebrates resilience and keeps hearts hopeful daily."},{"chapterId":5,"title":"Prayer","toneFocus":"Speak of salah as a gentle pause, emphasizing presence and breath over performance while honoring everyday distractions. It invites patience, softens doubts, and champions steady growth. It celebrates resilience and keeps hearts hopeful daily."},{"chapterId":6,"title":"Ramadan","toneFocus":"Describe Ramadan as a nurturing rhythm, inviting compassion for oneself and kindness toward others rather than strict punishment. It invites patience, softens doubts, and champions steady growth. It celebrates resilience and keeps hearts hopeful daily."},{"chapterId":7,"title":"Good Character","toneFocus":"Model good character through gentle encouragement acknowledge slips but focus on the next soft step forward. It invites patience, softens doubts, and champions steady growth. It celebrates resilience and keeps hearts hopeful daily."},{"chapterId":8,"title":"Peace & Respect","toneFocus":"Invite readers to practice peace through listening and curiosity, framing respect as earned through care rather than enforced rules. It invites patience, softens doubts, and champions steady growth. It celebrates resilience and keeps hearts hopeful daily."},{"chapterId":9,"title":"The Prophets","toneFocus":"Let prophetic journeys feel human mention persistence, setback, and divine support so readers can relate without guilt. It invites patience, softens doubts, and champions steady growth. It celebrates resilience and keeps hearts hopeful daily."},{"chapterId":10,"title":"The Mosque","toneFocus":"Paint mosque life as inclusive serenity, inviting anyone to wander through spiritual stillness without pressure to know every ritual. It invites patience, softens doubts, and champions steady growth. It celebrates resilience and keeps hearts hopeful daily."},{"chapterId":11,"title":"Halal Life","toneFocus":"Describe halal choices as mindful experiments rooted in honesty and compassion rather than rigid enforcement. It invites patience, softens doubts, and champions steady growth. It celebrates resilience and keeps hearts hopeful daily."},{"chapterId":12,"title":"Men & Women","toneFocus":"Frame gender relations through partnership, mutual respect, and shared dignity, using inclusive wording that avoids hierarchy. It invites patience, softens doubts, and champions steady growth. It celebrates resilience and keeps hearts hopeful daily."},{"chapterId":13,"title":"Becoming Muslim","toneFocus":"Highlight conversion as brave openness, assuring readers that vulnerability, questions, and seeking support are all honored steps. It invites patience, softens doubts, and champions steady growth. It celebrates resilience and keeps hearts hopeful daily."},{"chapterId":14,"title":"Eid Festivals","toneFocus":"Describe Eid celebrations with warmth focus on gratitude, simple sharing, and inclusive joy, no matter the setting. It invites patience, softens doubts, and champions steady growth. It celebrates resilience and keeps hearts hopeful daily."},{"chapterId":15,"title":"Afterlife","toneFocus":"Speak about the afterlife with hope and mercy, offering calm prompts rather than fear and reminding readers of Allah’s forgiveness. It invites patience, softens doubts, and champions steady growth. It celebrates resilience and keeps hearts hopeful daily."}]');

