/***/ "./resources/js/components/non_muslim_data/chapterToneGuidelines.json":
/*!****************************************************************************!*\
  !*** ./resources/js/components/non_muslim_data/chapterToneGuidelines.json ***!
  \****************************************************************************/
/***/ ((module) => {

module.exports = /*#__PURE__*/JSON.parse('[{"chapterId":1,"title":"One God","guidelines":["Describe Tawheed as a calm, unfolding conversation where every question brings the reader closer to understanding.","Avoid absolutes; use invitations like \\"consider this\\" or \\"one way to see it\\" so people feel safe exploring.","Remind readers that belief is a personal journey, not a checklist for success."]},{"chapterId":2,"title":"The Qur\'an","guidelines":["Frame the Qur\'an as a compassionate companion that meets each reader at their pace.","Use gentle language that honors uncertainty words such as \\"perhaps\\" or \\"explore\\" keep tone open.","Reassure readers that every attempt to connect with the text is worthy, even when progress feels slow."]},{"chapterId":3,"title":"The Prophet","guidelines":["Highlight the Prophet’s mercy and patience without making the reader feel they must immediately emulate perfection.","Invite reflection with phrases like \\"what stands out to you?\\" instead of corrective statements.","Use stories to encourage empathy, not guilt, guiding readers to draw lessons gently."]},{"chapterId":4,"title":"Main Practices","guidelines":["Talk about rituals as supportive anchors rather than rigid requirements.","Stress curiosity over correction when readers grapple with unfamiliar practices.","Offer small, flexible steps so readers can experiment without feeling judged."]},{"chapterId":5,"title":"Prayer","guidelines":["Let prayer feel like a safe pause, not an achievement to chase.","Acknowledge distractions with compassion, as shared human experiences.","Replace \\"should\\" language with collaborative phrasing such as \\"you might try\\" or \\"some find.\\""]},{"chapterId":6,"title":"Ramadan","guidelines":["Describe fasting as a shared rhythm that gently invites self-restraint, not punishment.","Celebrate the small wins each kind intention is meaningful even if imperfect.","Encourage readers to listen to their bodies and hearts while still honoring the spirit of Ramadan."]},{"chapterId":7,"title":"Good Character","guidelines":["Focus on gradual character shifts, using language that affirms effort rather than pointing out flaws.","Use inclusive \\"we\\" and \\"us\\" to model humility and shared striving.","Offer reminders that kindness begins with self-awareness, not self-criticism."]},{"chapterId":8,"title":"Peace & Respect","guidelines":["Describe peace as an invitation to listen, not a demand for agreement.","Show respect as something earned through consistent care instead of adhering to strict norms.","Encourage readers to practice dialogue with curiosity, not judgment."]},{"chapterId":9,"title":"The Prophets","guidelines":["Tell prophetic stories with reverence while allowing readers to witness human struggle, not perfection.","Prompt gentle questions like \\"what would you take from this?\\" rather than issuing commands.","Remind readers that learning from prophets means focusing on intent and growth, not comparison."]},{"chapterId":10,"title":"The Mosque","guidelines":["Present mosque spaces as welcoming havens where everyone is invited to belong slowly.","Stress hospitality and calm presence over rigid protocol.","Frame norms as guides, not gatekeepers, so readers don’t feel excluded."]},{"chapterId":11,"title":"Halal Life","guidelines":["Gently introduce halal choices as mindful invitations rather than strict edicts.","Acknowledge that readers come from varied backgrounds and may adapt the guidance at their own pace.","Highlight the heart behind halal integrity, honesty, compassion not just surface rules."]},{"chapterId":12,"title":"Men & Women","guidelines":["Use balanced, inclusive wording that honors both genders without favoring one viewpoint.","Encourage mutual respect through shared stories instead of prescriptive lists.","Avoid moralizing language; treat relationships as evolving partnerships framed by care."]},{"chapterId":13,"title":"Becoming Muslim","guidelines":["Speak of conversion as a personal, courageous step that deserves celebration and solitude when needed.","Offer encouragement that honors vulnerability \\"it’s okay to feel unsure\\" adds safety.","Reassure readers that seeking support is part of the journey, not evidence of weakness."]},{"chapterId":14,"title":"Eid Festivals","guidelines":["Describe festive moments through warmth and inclusion, inviting readers to join without pressure.","Highlight gratitude and reunion rather than expectations about flawless celebration.","Use upbeat yet grounded tone so readers feel welcome to celebrate in whatever way fits them."]},{"chapterId":15,"title":"Afterlife","guidelines":["Balance reminders about accountability with reassurance of Allah’s mercy and hope.","Invite reflection through calm prompts like \\"consider where you’d like things to end up.\\"","Frame preparation for the afterlife as a compassionate act toward one’s future self."]}]');

/***/ }),

